INSERT INTO lf_ops.reglas(id,codigo,categoria,titulo,descripcion,razon,valor_config,es_transversal,estado,origen) SELECT id,codigo,categoria,titulo,descripcion,razon,valor_config,es_transversal,estado,origen FROM jsonb_to_recordset($src$[{"id":229,"codigo":"REG_NIU_005","categoria":"niubiz","titulo":"Ambiente de pruebas antes de producción","descripcion":"Todo el flujo de checkout debe probarse en el ambiente sandbox de Niubiz antes de activar producción. Las credenciales de sandbox y producción son distintas y nunca se mezclan.","razon":"Errores en el checkout de producción impactan directamente en cobros reales.","valor_config":{"ambientes":["sandbox","produccion"],"mezcla_credenciales":false,"prueba_sandbox_obligatoria":true},"es_transversal":false,"estado":"VIGENTE","origen":"tecnico"},{"id":277,"codigo":"REG_CHK_014","categoria":"checkout","titulo":"Cancelación del plan sin penalidades","descripcion":"El usuario puede cancelar el cobro recurrente de su plan en cualquier momento desde \"Mis operaciones\". La cancelación no genera penalidades. La carta de no adeudo se emite solo cuando la deuda está totalmente cancelada.","razon":"Decisión comercial cerrada con los aliados B2B. Reduce la ansiedad de comprometerse a un plan largo.","valor_config":{"desde":"Mis operaciones","penalidades":false,"carta_no_adeudo":"al_cancelar_totalmente","cancelacion_permitida":true},"es_transversal":true,"estado":"VIGENTE","origen":"decision_producto"},{"id":289,"codigo":"REG_CHK_CUO_006","categoria":"checkout","titulo":"Cancelación del plan sin penalidades","descripcion":"El usuario puede cancelar el cobro recurrente del plan en cuotas en cualquier momento. No hay penalidades por cancelación anticipada. Esta condición debe estar visible en la pantalla de checkout antes del pago.","razon":"Decisión comercial cerrada con aliados B2B. Reduce la barrera de entrada al plan para usuarios que temen comprometerse a largo plazo.","valor_config":{"posicion":"bajo_checkbox_autorizacion","penalidad":false,"texto_visible":"Podrás cancelar tu plan cuando lo necesites. Sin penalidades.","cancelacion_permitida":true},"es_transversal":false,"estado":"VIGENTE","origen":"negocio"},{"id":13126,"codigo":"REG_CLIENT_PAYMENT_RECEIPT_REAL_EMAIL_001","categoria":"pago","titulo":"Los recibos de pago llegan al correo real del cliente","descripcion":"El recibo o comprobante de un pago confirmado se dirige exclusivamente al correo real del cliente registrado y validado por LF, nunca al identificador técnico Niubiz derivado de public.lf_global_config (scope PAGOS; config_key NIUBIZ_EMAIL_TEMPLATE y NIUBIZ_EMAIL_DOMAIN). El backend conserva separados customer_email y niubiz_technical_email, destinados respectivamente a recibos y al proveedor. La emisión del recibo exige PAYMENT_CONFIRMED autoritativo; la aceptación preliminar y los rebotes del correo técnico no confirman el pago ni modifican el destinatario. Si falta correo real, se registra y atiende la incidencia sin sustituirlo por correo técnico o genérico.","razon":"Preserva la entrega de comprobantes al cliente y evita que el identificador del formulario Niubiz se use como canal de comunicación o evidencia del pago.","valor_config":{"receipt_trigger":"PAYMENT_CONFIRMED_AUTHORITATIVE","separate_fields":["customer_email","niubiz_technical_email"],"receipt_email_source":"CUSTOMER_REAL_REGISTERED_VERIFIED_EMAIL","on_missing_real_email":"TRACEABLE_INCIDENT_NO_GENERIC_FALLBACK","production_authorized":false,"niubiz_email_config_refs":[{"scope":"PAGOS","config_key":"NIUBIZ_EMAIL_TEMPLATE"},{"scope":"PAGOS","config_key":"NIUBIZ_EMAIL_DOMAIN"}],"provider_identifier_source":"NIUBIZ_UNIQUE_TECHNICAL_EMAIL","customer_receipt_destination":"REAL_EMAIL_ONLY","provider_technical_email_not_receipt_destination":true},"es_transversal":false,"estado":"CANDIDATO","origen":"LF_IG_NIUBIZ_EMAIL_UNICO_20261118"}]$src$::jsonb) AS t(id integer,codigo text,categoria text,titulo text,descripcion text,razon text,valor_config jsonb,es_transversal boolean,estado text,origen text) ON CONFLICT (id) DO NOTHING;
